  'companyIntro.description': '长凌科技不只是卖配件，而是提供整套飞行解决方案。从产品选型到系统集成，从技术培训到售后保障，全程陪伴您的无人机项目落地。我们服务电力、物流、消防等500+企业客户，积累了丰富的实战经验。',
